import{_ as p,a0 as l,w as o,s as u,I as i,x as n,a1 as e,A as t,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何在 Linux 中验证 ISO 镜像 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中验证 ISO 镜像 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中验证 ISO 镜像 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中验证 ISO 镜像 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190805 How To Verify ISO Images In Linux","title":"如何在 Linux 中验证 ISO 镜像","tag":"201908","desc":""},"relativePath":"201908/20190805 How To Verify ISO Images In Linux.md","filePath":"[post].md"}'),g={name:"201908/20190805 How To Verify ISO Images In Linux.md"};function d(h,s,k,b,c,m){const a=l("Link");return o(),u("div",null,[s[21]||(s[21]=i("h1",{id:"如何在-linux-中验证-iso-镜像",tabindex:"-1"},[n("如何在 Linux 中验证 ISO 镜像 "),i("a",{class:"header-anchor",href:"#如何在-linux-中验证-iso-镜像","aria-label":"Permalink to “如何在 Linux 中验证 ISO 镜像”"},"​")],-1)),s[22]||(s[22]=i("p",null,[i("img",{src:"https://www.ostechnix.com/wp-content/uploads/2019/07/Verify-ISO-Images-In-Linux-720x340.png",alt:"如何在 Linux 中校验 ISO 镜像"})],-1)),i("p",null,[s[2]||(s[2]=n("你从喜爱的 Linux 发行版的官方网站或第三方网站下载了它的 ISO 镜像之后，接下来要做什么呢？是",-1)),e(a,{href:"https://www.ostechnix.com/etcher-beauitiful-app-create-bootable-sd-cards-usb-drives/"},{default:t(()=>[...s[0]||(s[0]=[n("创建可启动介质",-1)])]),_:1}),s[3]||(s[3]=n("并开始安装系统吗？并不是，请稍等一下。在开始使用它之前，强烈建议你检查一下你刚下载到本地系统中的 ISO 文件是否是下载镜像站点中 ISO 文件的一个精确拷贝。因为在前几年 ",-1)),e(a,{href:"https://blog.linuxmint.com/?p=2994"},{default:t(()=>[...s[1]||(s[1]=[n("Linux Mint 的网站被攻破了",-1)])]),_:1}),s[4]||(s[4]=n("，并且攻击者创建了一个包含后门的经过修改的 Linux Mint ISO 文件。 所以验证下载的 Linux ISO 镜像的可靠性和完整性是非常重要的一件事儿。假如你不知道如何在 Linux 中验证 ISO 镜像，本次的简要介绍将给予你帮助，请接着往下看！",-1))]),s[23]||(s[23]=r(`<h3 id="在-linux-中验证-iso-镜像" tabindex="-1">在 Linux 中验证 ISO 镜像 <a class="header-anchor" href="#在-linux-中验证-iso-镜像" aria-label="Permalink to “在 Linux 中验证 ISO 镜像”">​</a></h3><p>我们可以使用 ISO 镜像的“校验和”来验证 ISO 镜像。校验和是一系列字母和数字的组合，用来检验下载文件的数据是否有错以及验证其可靠性和完整性。当前存在不同类型的校验和，例如 SHA-0、SHA-1、SHA-2（224、256、384、512）和 MD5。MD5 校验和最为常用，但对于现代的 Linux 发行版，SHA-256 最常被使用。</p><p>我们将使用名为 <code>gpg</code> 和 <code>sha256</code> 的两个工具来验证 ISO 镜像的可靠性和完整性。</p><h4 id="下载校验和及签名" tabindex="-1">下载校验和及签名 <a class="header-anchor" href="#下载校验和及签名" aria-label="Permalink to “下载校验和及签名”">​</a></h4><p>针对本篇指南的目的，我将使用 Ubuntu 18.04 LTS 服务器 ISO 镜像来做验证，但对于其他的 Linux 发行版应该也是适用的。</p><p>在靠近 Ubuntu 下载页的最上端，你将看到一些额外的文件（校验和及签名），正如下面展示的图片那样：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/07/Ubuntu-18.04-checksum-and-signature.png" alt="Ubuntu 18.04 的校验和及签名"></p><p>其中名为 <code>SHA256SUMS</code> 的文件包含了这里所有可获取镜像的校验和，而 <code>SHA256SUMS.gpg</code> 文件则是这个文件的 GnuPG 签名。在下面的步骤中，我们将使用这个签名文件来 <strong>验证</strong> 校验和文件。</p><p>下载 Ubuntu 的 ISO 镜像文件以及刚才提到的那两个文件，然后将它们放到同一目录下，例如这里的 <code>ISO</code> 目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls ISO/</span></span>
<span class="line"><span>SHA256SUMS SHA256SUMS.gpg ubuntu-18.04.2-live-server-amd64.iso</span></span></code></pre></div><p>如你所见，我已经下载了 Ubuntu 18.04.2 LTS 服务器版本的镜像，以及对应的校验和文件和签名文件。</p><h4 id="下载有效的签名秘钥" tabindex="-1">下载有效的签名秘钥 <a class="header-anchor" href="#下载有效的签名秘钥" aria-label="Permalink to “下载有效的签名秘钥”">​</a></h4><p>现在，使用下面的命令来下载正确的签名秘钥：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gpg --keyid-format long --keyserver hkp://keyserver.ubuntu.com --recv-keys 0x46181433FBB75451 0xD94AA3F0EFE21092</span></span></code></pre></div><p>示例输出如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gpg: key D94AA3F0EFE21092: 57 signatures not checked due to missing keys</span></span>
<span class="line"><span>gpg: key D94AA3F0EFE21092: public key &quot;Ubuntu CD Image Automatic Signing Key (2012) &lt;[email protected]&gt;&quot; imported</span></span>
<span class="line"><span>gpg: key 46181433FBB75451: 105 signatures not checked due to missing keys</span></span>
<span class="line"><span>gpg: key 46181433FBB75451: public key &quot;Ubuntu CD Image Automatic Signing Key &lt;[email protected]&gt;&quot; imported</span></span>
<span class="line"><span>gpg: no ultimately trusted keys found</span></span>
<span class="line"><span>gpg: Total number processed: 2</span></span>
<span class="line"><span>gpg: imported: 2</span></span></code></pre></div><h4 id="验证-sha-256-校验和" tabindex="-1">验证 SHA-256 校验和 <a class="header-anchor" href="#验证-sha-256-校验和" aria-label="Permalink to “验证 SHA-256 校验和”">​</a></h4><p>接下来我们将使用签名来验证校验和文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gpg --keyid-format long --verify SHA256SUMS.gpg SHA256SUMS</span></span></code></pre></div><p>下面是示例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gpg: Signature made Friday 15 February 2019 04:23:33 AM IST</span></span>
<span class="line"><span>gpg: using DSA key 46181433FBB75451</span></span>
<span class="line"><span>gpg: Good signature from &quot;Ubuntu CD Image Automatic Signing Key &lt;[email protected]&gt;&quot; [unknown]</span></span>
<span class="line"><span>gpg: WARNING: This key is not certified with a trusted signature!</span></span>
<span class="line"><span>gpg: There is no indication that the signature belongs to the owner.</span></span>
<span class="line"><span>Primary key fingerprint: C598 6B4F 1257 FFA8 6632 CBA7 4618 1433 FBB7 5451</span></span>
<span class="line"><span>gpg: Signature made Friday 15 February 2019 04:23:33 AM IST</span></span>
<span class="line"><span>gpg: using RSA key D94AA3F0EFE21092</span></span>
<span class="line"><span>gpg: Good signature from &quot;Ubuntu CD Image Automatic Signing Key (2012) &lt;[email protected]&gt;&quot; [unknown]</span></span>
<span class="line"><span>gpg: WARNING: This key is not certified with a trusted signature!</span></span>
<span class="line"><span>gpg: There is no indication that the signature belongs to the owner.</span></span>
<span class="line"><span>Primary key fingerprint: 8439 38DF 228D 22F7 B374 2BC0 D94A A3F0 EFE2 1092</span></span></code></pre></div><p>假如你在输出中看到 <code>Good signature</code> 字样，那么该校验和文件便是由 Ubuntu 开发者制作的，并且由秘钥文件的所属者签名认证。</p><h4 id="检验下载的-iso-文件" tabindex="-1">检验下载的 ISO 文件 <a class="header-anchor" href="#检验下载的-iso-文件" aria-label="Permalink to “检验下载的 ISO 文件”">​</a></h4><p>下面让我们继续检查下载的 ISO 文件是否和所给的校验和相匹配。为了达到该目的，只需要运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sha256sum -c SHA256SUMS 2&gt;&amp;1 | grep OK</span></span>
<span class="line"><span>ubuntu-18.04.2-live-server-amd64.iso: OK</span></span></code></pre></div><p>假如校验和是匹配的，你将看到 <code>OK</code> 字样，这意味着下载的文件是合法的，没有被改变或篡改过。</p><p>假如你没有获得类似的输出，或者看到不同的输出，则该 ISO 文件可能已经被修改过或者没有被正确地下载。你必须从一个更好的下载源重新下载该文件。</p><p>某些 Linux 发行版已经在它的下载页面中包含了校验和。例如 Pop!_os 的开发者在他们的下载页面中提供了所有 ISO 镜像的 SHA-256 校验和，这样你就可以快速地验证这些 ISO 镜像。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/07/Pop-os-SHA256-sum.png" alt="Pop os 位于其下载页面中的 SHA256 校验和"></p><p>在下载完 ISO 镜像文件后，可以使用下面的命令来验证它们：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sha256sum Soft_backup/ISOs/pop-os_18.04_amd64_intel_54.iso</span></span></code></pre></div><p>示例输出如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>680e1aa5a76c86843750e8120e2e50c2787973343430956b5cbe275d3ec228a6 Soft_backup/ISOs/pop-os_18.04_amd64_intel_54.iso</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/07/Pop-os-SHA256-sum-value.png" alt="Pop os 的 SHA256 校验和的值"></p><p>在上面的输出中，以 <code>680elaa</code> 开头的部分为 SHA-256 校验和的值。请将该值与位于下载页面中提供的 SHA-256 校验和的值进行比较，如果这两个值相同，那说明这个下载的 ISO 文件是合法的，与它的原有状态相比没有经过更改或者篡改。万事俱备，你可以进行下一步了！</p><p>上面的内容便是我们如何在 Linux 中验证一个 ISO 文件的可靠性和完整性的方法。无论你是从官方站点或者第三方站点下载 ISO 文件，我们总是推荐你在使用它们之前做一次简单的快速验证。希望本篇的内容对你有所帮助。</p><p>参考文献：</p>`,37)),i("ul",null,[i("li",null,[e(a,{href:"https://tutorials.ubuntu.com/tutorial/tutorial-how-to-verify-ubuntu"},{default:t(()=>[...s[5]||(s[5]=[n("https://tutorials.ubuntu.com/tutorial/tutorial-how-to-verify-ubuntu",-1)])]),_:1})])]),s[24]||(s[24]=i("hr",null,null,-1)),i("p",null,[s[7]||(s[7]=n("via: ",-1)),e(a,{href:"https://www.ostechnix.com/how-to-verify-iso-images-in-linux/"},{default:t(()=>[...s[6]||(s[6]=[n("https://www.ostechnix.com/how-to-verify-iso-images-in-linux/",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=n("作者：",-1)),e(a,{href:"https://www.ostechnix.com/author/sk/"},{default:t(()=>[...s[8]||(s[8]=[n("sk",-1)])]),_:1}),s[13]||(s[13]=n(" 选题：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[9]||(s[9]=[n("lujun9972",-1)])]),_:1}),s[14]||(s[14]=n(" 译者：",-1)),e(a,{href:"https://github.com/FSSlc"},{default:t(()=>[...s[10]||(s[10]=[n("FSSlc",-1)])]),_:1}),s[15]||(s[15]=n(" 校对：",-1)),e(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[11]||(s[11]=[n("wxy",-1)])]),_:1})]),i("p",null,[s[18]||(s[18]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[16]||(s[16]=[n("LCTT",-1)])]),_:1}),s[19]||(s[19]=n(" 原创编译，",-1)),e(a,{href:"https://linux.cn/"},{default:t(()=>[...s[17]||(s[17]=[n("Linux中国",-1)])]),_:1}),s[20]||(s[20]=n(" 荣誉推出",-1))])])}const y=p(g,[["render",d]]);export{x as __pageData,y as default};
